la a0, testdata
li a5, 5600
add a0, a0, a5
# Load data into v0 register group.
vsetvli t1, x0, e32,m1,tu,mu
vle32.v v0, (a0)
# Move a0 to test data area.
la a0, testdata
li a5, 5616
add a0, a0, a5
# Load data into v8 register group.
vsetvli t1, x0, e8,m8,tu,mu
vle8.v v8, (a0)
# Move a0 to test data area.
la a0, testdata
li a5, 5744
add a0, a0, a5
# Load data into v16 register group.
vsetvli t1, x0, e8,m8,tu,mu
vle8.v v16, (a0)
# -------------- TEST BEGIN --------------
li s0, 0
li t0, 127
vsetvli t1, t0, e8,m8,tu,mu
vssra.vx v8, v16, s0
# -------------- TEST END --------------
la a0, resultdata
